INSERT INTO `FAQ` (`ID`, `Pertanyaan`, `Jawaban`, `Status`, `Kategori`, `Tanggal_Pembaruan`) VALUES
('FAQ-1', 'Apa itu OSS?', 'OSS (Online Single Submission) adalah sistem perizinan berusaha terintegrasi secara elektronik yang digunakan pelaku usaha untuk mengajukan dan mengelola perizinan berusaha. Akses melalui https://oss.go.id/.', 'AKTIF', 'Informasi Dasar', NULL),
('FAQ-2', 'Apa itu NIB?', 'NIB (Nomor Induk Berusaha) adalah identitas resmi pelaku usaha yang diterbitkan melalui sistem OSS dan menjadi bagian dari perizinan berusaha sesuai tingkat risiko kegiatan usaha.', 'AKTIF', 'Informasi Dasar', NULL),
('FAQ-3', 'Apakah semua usaha wajib memiliki NIB?', 'Pelaku usaha wajib memenuhi ketentuan perizinan berusaha yang berlaku. Jenis perizinan dan persyaratannya ditentukan antara lain oleh bidang usaha dan tingkat risiko kegiatan usaha.', 'AKTIF', 'Informasi Dasar', NULL),
('FAQ-4', 'Apakah NIB sama dengan izin usaha?', 'Tidak selalu. Selain NIB, kegiatan usaha tertentu memerlukan Sertifikat Standar, Izin, atau persyaratan lain sesuai tingkat risiko dan ketentuan sektoral.', 'AKTIF', 'Informasi Dasar', NULL),
('FAQ-5', 'Apakah usaha mikro dan kecil dapat mengurus NIB secara online?', 'Ya. Pelaku usaha dapat mengajukan NIB melalui OSS dengan mengisi data sesuai profil dan kegiatan usahanya. Panduan tersedia di https://oss.go.id/id/panduan.', 'AKTIF', 'Informasi Dasar', NULL),
('FAQ-6', 'Apa saja persyaratan untuk mengurus NIB?', 'Persyaratan mengikuti jenis pelaku usaha dan kegiatan yang diajukan. Umumnya pemohon perlu menyiapkan data identitas, alamat usaha, bidang usaha/KBLI, lokasi kegiatan, serta data pendukung yang diminta sistem OSS.', 'AKTIF', 'Persyaratan', NULL),
('FAQ-7', 'Apa itu KBLI dan mengapa penting?', 'KBLI adalah Klasifikasi Baku Lapangan Usaha Indonesia. Kode KBLI digunakan untuk mengidentifikasi kegiatan usaha dan membantu menentukan jenis perizinan serta kewajiban yang harus dipenuhi.', 'AKTIF', 'Persyaratan', NULL),
('FAQ-8', 'Bagaimana cara mengurus perizinan berusaha?', 'Secara umum, tahapannya adalah masuk atau membuat akun OSS, melengkapi data pelaku usaha, memilih KBLI, mengisi data kegiatan usaha, memenuhi persyaratan yang diminta, lalu mengunduh dokumen perizinan yang telah diterbitkan.', 'AKTIF', 'Proses Perizinan', NULL),
('FAQ-9', 'Apakah semua perizinan dapat selesai pada hari yang sama?', 'Tidak selalu. Waktu penyelesaian bergantung pada jenis perizinan, kelengkapan dokumen, kebutuhan verifikasi, dan pemenuhan persyaratan. Acuan waktu pelayanan dapat dilihat pada Standar Pelayanan DPMPTSP atau instansi yang berwenang.', 'AKTIF', 'Proses Perizinan', NULL),
('FAQ-10', 'Apakah pengurusan perizinan harus datang langsung ke kantor DPMPTSP?', 'Sebagian besar proses perizinan berusaha dilakukan melalui OSS secara elektronik. Jika membutuhkan bantuan atau terdapat persyaratan yang memerlukan verifikasi, pemohon dapat menggunakan kanal layanan resmi DPMPTSP Kota Tegal.', 'AKTIF', 'Proses Perizinan', NULL),
('FAQ-11', 'Bagaimana jika saya salah memilih KBLI?', 'Periksa kembali kegiatan usaha yang dimasukkan pada OSS. Jika data sudah tersimpan atau dokumen telah terbit, gunakan prosedur perubahan data atau perizinan yang tersedia dan pastikan kode KBLI sesuai kegiatan usaha sebenarnya.', 'AKTIF', 'Proses Perizinan', NULL),
('FAQ-12', 'Apa yang dimaksud perizinan berusaha berbasis risiko?', 'Perizinan berusaha berbasis risiko adalah pendekatan yang menentukan jenis perizinan dan kewajiban berdasarkan tingkat risiko kegiatan usaha. Tingkat risiko terdiri dari rendah, menengah rendah, menengah tinggi, dan tinggi.', 'AKTIF', 'Tingkat Risiko', NULL),
('FAQ-13', 'Apa perbedaan dokumen perizinan berdasarkan tingkat risiko?', 'Secara umum, risiko rendah memerlukan NIB; menengah rendah memerlukan NIB dan Sertifikat Standar; menengah tinggi memerlukan NIB dan Sertifikat Standar dengan verifikasi; sedangkan risiko tinggi memerlukan NIB dan Izin. Persyaratan dasar dan sektoral tetap dapat berlaku.', 'AKTIF', 'Tingkat Risiko', NULL),
('FAQ-14', 'Apa itu KKPR?', 'KKPR adalah Kesesuaian Kegiatan Pemanfaatan Ruang, yaitu persyaratan terkait kesesuaian lokasi kegiatan usaha dengan ketentuan tata ruang. Kewajiban dan mekanismenya mengikuti kondisi lokasi serta ketentuan yang berlaku.', 'AKTIF', 'Persyaratan', NULL),
('FAQ-15', 'Apakah setiap usaha membutuhkan persetujuan lingkungan?', 'Tidak selalu dengan jenis dokumen yang sama. Kewajiban lingkungan ditentukan berdasarkan jenis, skala, karakteristik, dan dampak kegiatan usaha sesuai ketentuan yang berlaku. Periksa persyaratan pada OSS dan instansi lingkungan yang berwenang.', 'AKTIF', 'Persyaratan', NULL),
('FAQ-16', 'Apakah NIB sudah cukup untuk langsung menjalankan usaha?', 'Belum tentu. Pastikan seluruh kewajiban perizinan untuk kegiatan operasional atau komersial telah dipenuhi. Usaha tertentu memerlukan Sertifikat Standar, Izin, atau persyaratan lainnya.', 'AKTIF', 'Proses Perizinan', NULL),
('FAQ-17', 'Bagaimana jika alamat usaha berubah?', 'Periksa fitur perubahan data pelaku usaha atau proyek pada akun OSS. Siapkan alamat terbaru dan penuhi persyaratan tambahan jika perubahan lokasi berdampak pada tata ruang atau persyaratan lainnya.', 'AKTIF', 'Perubahan Data', NULL),
('FAQ-18', 'Bagaimana jika NIB atau dokumen perizinan hilang?', 'Masuk ke akun OSS yang digunakan saat pengajuan, kemudian periksa data usaha dan bagian dokumen perizinan untuk mengunduh kembali dokumen yang tersedia. Jika terkendala, gunakan kanal bantuan resmi OSS.', 'AKTIF', 'Kendala OSS', NULL),
('FAQ-19', 'Bagaimana jika saya lupa kata sandi atau tidak dapat masuk ke OSS?', 'Gunakan fitur pemulihan akun pada halaman OSS. Pastikan email atau nomor kontak yang terdaftar masih dapat diakses. Jika kendala berlanjut, hubungi layanan bantuan resmi OSS.', 'AKTIF', 'Kendala OSS', NULL),
('FAQ-20', 'Mengapa pengajuan perizinan saya belum selesai atau masih menunggu verifikasi?', 'Penyebabnya dapat berupa data yang belum lengkap, persyaratan yang belum dipenuhi, atau verifikasi instansi berwenang yang belum selesai. Periksa status permohonan dan notifikasi pada akun OSS untuk mengetahui tindak lanjutnya.', 'AKTIF', 'Kendala OSS', NULL),
('FAQ-21', 'Bagaimana jika data NIB tidak sesuai dengan data usaha saya?', 'Periksa data pada akun OSS dan gunakan prosedur perubahan data atau perizinan yang sesuai. Jika perubahan tidak dapat dilakukan melalui sistem, mintalah petunjuk kepada layanan bantuan OSS atau DPMPTSP sesuai kewenangannya.', 'AKTIF', 'Perubahan Data', NULL),
('FAQ-22', 'Di mana saya dapat memperoleh informasi persyaratan perizinan di Kota Tegal?', 'Masyarakat dapat melihat menu Jenis Pelayanan, Standar Pelayanan, dan SOP pada website DPMPTSP Kota Tegal. Untuk jenis izin tertentu, periksa juga persyaratan pada sistem OSS.', 'AKTIF', 'Layanan DPMPTSP', NULL),
('FAQ-23', 'Bagaimana cara mengetahui SOP dan standar waktu pelayanan?', 'Buka menu Standar Pelayanan atau SOP pada website DPMPTSP Kota Tegal. Informasi tersebut menjadi acuan untuk mengetahui persyaratan, prosedur, waktu penyelesaian, biaya atau tarif jika ada, serta produk layanan.', 'AKTIF', 'Layanan DPMPTSP', NULL),
('FAQ-24', 'Apakah DPMPTSP dapat membantu jika saya mengalami kesulitan mengurus perizinan?', 'Pemohon dapat menghubungi atau mendatangi kanal pelayanan resmi DPMPTSP Kota Tegal untuk memperoleh informasi dan bantuan sesuai kewenangan. Siapkan data usaha, jenis layanan, serta keterangan kendala.', 'AKTIF', 'Layanan DPMPTSP', NULL),
('FAQ-25', 'Bagaimana cara menyampaikan pengaduan terkait pelayanan perizinan?', 'Sampaikan pengaduan melalui kanal pengaduan resmi pada menu Hubungi Kami di website DPMPTSP Kota Tegal. Sertakan kronologi, tanggal kejadian, jenis layanan, dan bukti pendukung yang relevan. Jangan mencantumkan kata sandi atau data pribadi yang tidak diperlukan.', 'AKTIF', 'Pengaduan', NULL),
('FAQ-26', 'Apakah pengurusan perizinan berusaha dikenakan biaya?', 'Biaya atau tarif mengikuti ketentuan peraturan perundang-undangan untuk jenis layanan yang bersangkutan. Periksa Standar Pelayanan dan informasi resmi terkait. Hindari pembayaran ke rekening pribadi atau pihak yang tidak berwenang.', 'AKTIF', 'Biaya', NULL);
